#!/bin/sh
# PreToolUse: refuse edits to generated or source-of-truth files.
file=$(jq -r '.tool_input.file_path // empty')
case "$file" in
  */src/wyrestorm_networkhd/_version.py) echo "_version.py is generated by setuptools-scm; don't edit it." >&2; exit 2 ;;
  */docs/resources/*.pdf) echo "The NetworkHD API PDF is the spec; don't modify it." >&2; exit 2 ;;
esac
exit 0
